function resolveTemplateColor(role, primaryColor, altColor) {
  if (role === 'p') return { color: primaryColor, colorRole: 'primary' };
  if (role === 'a') return { color: altColor, colorRole: 'alt' };
  if (role === '_') return { color: 'transparent', colorRole: 'custom', isVoid: true };
  return { color: role, colorRole: 'custom' };
}

function makeBrick(segment, primaryColor, altColor) {
  const resolved = resolveTemplateColor(segment.r, primaryColor, altColor);

  return {
    id: tid(),
    units: segment.u,
    isVoid: Boolean(resolved.isVoid),
    isVertical: !resolved.isVoid && Number(segment.v) > 1,
    verticalUnits: Number(segment.v) || 1,
    color: resolved.color,
    colorRole: resolved.colorRole
  };
}

function generateRows(type, primaryColor, altColor) {
  const template = SVG_TEMPLATES.find(item => item.id === type) || SVG_TEMPLATES[0];
  return template.rows.map(row => row.map(segment => makeBrick(segment, primaryColor, altColor)));
}

export default function TemplateMenu({ primaryColor, altColor, onLoad }) {
  const [open, setOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 });
  const buttonRef = useRef(null);

  const toggleOpen = () => {
    const rect = buttonRef.current?.getBoundingClientRect();
    if (rect) {
      setMenuPosition({
        top: rect.bottom + 4,
        left: Math.max(8, Math.min(rect.left, window.innerWidth - 272))
      });
    }
    setOpen(v => !v);
  };

  return (
    <div className="relative flex-shrink-0">
      <button
        ref={buttonRef}
        onClick={toggleOpen}
        className="flex items-center gap-1.5 px-2.5 py-1.5 rounded text-xs hover:bg-accent text-muted-foreground transition-colors"
      >
        <LayoutTemplate className="w-3.5 h-3.5" />
        <span className="hidden sm:inline">Templates</span>
        <ChevronDown className="w-3 h-3" />
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div
            className="fixed z-[220] max-h-[70vh] w-64 overflow-y-auto rounded-lg border border-border bg-card py-1 shadow-xl"
            style={{ top: menuPosition.top, left: menuPosition.left }}
          >
            {SVG_TEMPLATES.map(t => (
              <button
                key={t.id}
                onClick={() => {
                  const rows = generateRows(t.id, primaryColor, altColor);
                  onLoad(rows);
                  setOpen(false);
                }}
                className="w-full text-left px-3 py-2.5 hover:bg-accent transition-colors"
              >
                <div className="text-xs font-medium text-foreground">{t.name}</div>
                <div className="text-[10px] text-muted-foreground mt-0.5">{t.desc}</div>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}